from math import erf, exp, log, sqrt, pi

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
    return K * exp(-r * T) * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)

def bs_vega(S, K, r, sigma, T, q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return S * exp(-q * T) * sqrt(T) * exp(-d1 * d1 / 2) / sqrt(2 * pi)

import numpy as np
import pandas as pd   # own line: the app loads packages from the imports it can read
import numpy as np, pandas as pd
from math import erf, exp, log, sqrt

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
    return K * exp(-r * T) * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)

def true_iv(K, T, S=100.0, r=0.05, q=0.01):
    m = log(K / (S * exp((r - q) * T))) / sqrt(T)       # moneyness per root year
    atm = 0.22 - 0.045 * exp(-T / 0.3)                   # term structure: rises with T
    return atm - 0.08 * m + 0.10 * m * m                 # skew and smile

def make_chain(seed=2320, S=100.0, r=0.05, q=0.01):
    rng = np.random.default_rng(seed)
    rows = []
    for T in [1 / 12, 2 / 12, 3 / 12, 6 / 12, 1.0]:
        for K in range(70, 131, 5):
            for kind in ("call", "put"):
                mid = bs_price(S, K, r, true_iv(K, T, S, r, q), T, kind, q)
                half = max(0.025, 0.03 * mid)
                noise = 0.2 * half * rng.standard_normal()
                bid = max(round(mid - half + noise, 2), 0.0)
                ask = round(mid + half + noise, 2)
                rows.append([T, K, kind, bid, ask, int(rng.integers(0, 5000)), 0.0])
    df = pd.DataFrame(rows, columns=["T", "strike", "type", "bid", "ask", "volume", "age_min"])
    bad = rng.choice(len(df), 9, replace=False)
    df.loc[bad[:3], "bid"] = 0.0                                          # zero bids
    df.loc[bad[3:5], "bid"] = df.loc[bad[3:5], "ask"] + 0.05              # crossed
    df.loc[bad[5:7], "age_min"] = 240.0                                   # stale
    df.loc[bad[7:], "ask"] = (df.loc[bad[7:], "ask"] * 1.6).round(2)      # wide
    return df

def mid(df):
    m = (df["bid"] + df["ask"]) / 2
    return m.where(df["bid"] > 0)

def clean_quotes(df, max_age_min=30, max_rel_spread=0.5):
    m = (df["bid"] + df["ask"]) / 2
    keep = ((df["bid"] > 0) & (df["bid"] <= df["ask"])
            & (df["age_min"] <= max_age_min)
            & ((df["ask"] - df["bid"]) / m < max_rel_spread))
    return df[keep].reset_index(drop=True)

def implied_forward(df_T, r, T):
    w = df_T.assign(mid=mid(df_T)).pivot(index="strike", columns="type", values="mid")
    if "call" not in w or "put" not in w:
        return float("nan")
    w = w.dropna(subset=["call", "put"])
    if len(w) < 3:
        return float("nan")
    F = w.index + exp(r * T) * (w["call"] - w["put"])
    return float(np.median(F))

def otm_quotes(df_T, F):
    keep = ((df_T["type"] == "put") & (df_T["strike"] < F)) | ((df_T["type"] == "call") & (df_T["strike"] >= F))
    return df_T[keep].sort_values("strike").reset_index(drop=True)

from math import pi

def bs_vega(S, K, r, sigma, T, q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return S * exp(-q * T) * sqrt(T) * exp(-d1 * d1 / 2) / sqrt(2 * pi)

def implied_vol(price, S, K, r, T, kind="call", q=0.0):
    """Volatility at which bs_price matches price, by Newton's method with a bisection fallback."""
    if kind == "call":
        lower, upper = max(S * exp(-q * T) - K * exp(-r * T), 0.0), S * exp(-q * T)
    elif kind == "put":
        lower, upper = max(K * exp(-r * T) - S * exp(-q * T), 0.0), K * exp(-r * T)
    else:
        raise ValueError("kind must be 'call' or 'put'")
    if not lower < price < upper:
        raise ValueError("no volatility fits this price")
    lo, hi, sigma = 1e-4, 5.0, 0.2
    for _ in range(50):
        diff = bs_price(S, K, r, sigma, T, kind, q) - price
        if abs(diff) < 1e-12:
            return sigma
        if diff > 0:
            hi = sigma            # price too high: the answer is below sigma
        else:
            lo = sigma            # price too low: the answer is above sigma
        v = bs_vega(S, K, r, sigma, T, q)
        new = sigma - diff / v if v > 1e-12 else hi + 1.0
        if not lo < new < hi:
            new = (lo + hi) / 2   # Newton left the bracket: bisect instead
        if abs(new - sigma) < 1e-14:
            return new
        sigma = new
    return sigma

def smile(clean, T, S, r, q):
    """OTM quotes of one expiry with standardised moneyness m and the implied vol of the mid."""
    df_T = clean[np.isclose(clean["T"], T)]
    F = S * exp((r - q) * T)
    otm = otm_quotes(df_T, F)
    rows = []
    for K, kind, b, a in zip(otm["strike"], otm["type"], otm["bid"], otm["ask"]):
        try:
            iv = implied_vol((b + a) / 2, S, K, r, T, kind, q)
        except ValueError:
            iv = float("nan")
        rows.append([K, log(K / F) / sqrt(T), iv])
    return pd.DataFrame(rows, columns=["strike", "m", "iv"])

clean = clean_quotes(make_chain())
sm1 = smile(clean, 1.0, 100.0, 0.05, 0.01).dropna()
k1 = np.log(sm1['strike'] / (100 * np.exp(0.04))).to_numpy()
w1 = (sm1['iv'] ** 2 * 1.0).to_numpy()

widget.model:
**1. The skew that looks three times steeper.** IV(90) − IV(110) is 0.0596 at one month and 0.0179 at one year, a ratio of 3.33. Standardised moneyness $m = \ln(K/F)/\sqrt{T}$ divides by $\sqrt{T}$, so £20 of strike is $\sqrt{12} = 3.46$ times more $m$ at one month. In $m$ the fitted skews are $b = -0.0767$ and $-0.0799$: the same within the noise. The one-month smile is steeper per £ because the same £ is a bigger move in standard deviations, not because short-dated puts are richer. Nothing to trade.

**2. The negative forward variance.** Total variance must not fall with expiry at a fixed $k = \ln(K/F)$: $\sigma_{1,2}^2 = (w_2 - w_1)/(T_2 - T_1) < 0$ means $w_{1Y} < w_{6M}$, a calendar arbitrage if the prices were real. Likely causes, in the order I would check them:
- a stale or bad one-year quote (check `age_min`, the spread, the bid-ask vols);
- the two vols read at different points, one at the spot and one at the forward (at one year $F = 104.08$, a 0.34-point shift: too small alone here, but enough between close expiries);
- a wrong $q$ or $r$ for one expiry, which moves its forward and so its $m$;
- vols interpolated linearly in $T$ somewhere upstream, which can bulge $w$;
- an extrapolated wing: the queried strike lies outside one expiry's quotes.
The fix is in the data, not the formula: `forward_vol` should raise, the dashboard should log the pair, and the surface should not be published until the check passes.

**3. Results note: Implied volatility surface.**
Smiles were fitted per expiry as $\sigma(m) = a + bm + cm^2$ to out-of-the-money mids after cleaning (4, 7, 9, 11 and 11 quotes). Skew and curvature are stable across expiries ($b \approx -0.08$, $c \approx 0.10$); the level rises from 0.185 at one month to 0.219 at one year. Expiries are joined by linear interpolation of total variance in $T$ at fixed log-moneyness, which preserves calendar order when the nodes are ordered; outside the nodes the vol is held flat and flagged. What failed: the one-month fit rests on four quotes between 90 and 105, so its wings are extrapolated (1.97 vol points low at £70). The forward vol between six months and one year came out negative on the first run, traced to [the cause found above]. Next: weight fits by the bid-ask vol band, fit SVI for the wings, and run the arbitrage checks of l15 before publishing.
